import (
	context "context"
	fern "github.com/openapi-pdf-download/fern"
	fernclient "github.com/openapi-pdf-download/fern/client"
)

client := fernclient.NewClient()
response, err := client.AssetReport.Get(
	context.TODO(),
	&fern.AssetReportPdfGetRequest{
		AssetReportToken: "asset_report_token",
	},
)

